MAXLEN = 9
def clean(ws, exclude=()):
    seen, out = set(exclude), []
    for w in ws:
        if w.isalpha() and w.islower() and 3 <= len(w) <= MAXLEN and w not in seen:
            seen.add(w); out.append(w)
    return sorted(out)
obj = clean(OBJ); mod = clean(MOD, obj)
def trim(obj, mod, total=2048):
    """Drop the longest words that share a 4-letter prefix until the list fits."""
    while len(obj) + len(mod) > total:
        pre = collections.Counter(w[:4] for w in obj + mod)
        w = max(obj + mod, key=lambda w: (pre[w[:4]] > 1, len(w), w))
        (obj if w in obj else mod).remove(w)
    return obj, mod
obj, mod = trim(obj, mod)
open("data/memory/words.txt", "w").write("\n".join(obj + mod) + "\n")
open("data/memory/objects.txt", "w").write("\n".join(obj) + "\n")
open("data/memory/modifiers.txt", "w").write("\n".join(mod) + "\n")
allw = obj + mod
pre = collections.Counter(w[:4] for w in allw)
bip = set(open("data/english.txt").read().split())
print(f"objects {len(obj)} ({100*len(obj)/len(allw):.0f}%)  modifiers {len(mod)}  total {len(allw)} / 2048")
print(f"dropped for length > {MAXLEN}: {sum(1 for w in set(OBJ+MOD) if len(w) > MAXLEN)}")
print(f"words sharing a 4-letter prefix with another: {sum(c for c in pre.values() if c > 1)}")
print(f"also in BIP39: {len(bip & set(allw))}")
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
def draw(): return random.choice(obj) if random.random() < len(obj) / len(allw) else random.choice(mod).upper()
for key in range(2):
    print(f"\nexample key {key + 1} (objects lower case, MODIFIERS upper case)")
    for r in range(7):
        print(f"  {'room ' + str(r + 1) if r < 6 else 'parity'}:  " + "  ".join(draw() for _ in range(4)))
N = 200000; bad = collections.Counter()
for _ in range(N):
    rooms = [[random.random() < len(obj) / len(allw) for _ in range(4)] for _ in range(7)]
    empty = sum(1 for r in rooms if not any(r))
    spare = sum(max(0, sum(r) - 1) for r in rooms)
    bad[(min(empty, 3), empty > 0 and rooms[6].count(True) - (0 if any(rooms[6]) else 0) < sum(1 for r in rooms[:6] if not any(r)))] += 1
no = sum(v for (e, _), v in bad.items() if e > 0)
unfix = sum(v for (e, f), v in bad.items() if e > 0 and f)
print(f"\nkeys (24+4, seven rooms of four) with an object-free room: {100 * no / N:.1f}%")
print(f"  of all keys, not fixable by borrowing objects from the parity room alone: {100 * unfix / N:.2f}%")
